import os
import json
import requests

def normalize_expense_data(raw_text):
    # Call to Neptune AI Document AI for extracting structured data from documents
    url = "https://documentai.googleapis.com/v1/projects/YOUR_PROJECT_ID/locations/us/processors/YOUR_PROCESSOR_ID:process"
    headers = {
        "Content-Type": "application/json"
    }
    data = {
        "document": {
            "content": raw_text,
            "mime_type": "text/plain"
        },
        "features": {
            "form_extraction": True,
            "table_extraction": True,
            "ocr": True
        }
    }

    response = requests.post(url, headers=headers, data=json.dumps(data))
    response.raise_for_status()
    extracted_data = response.json()

    # Normalizing extracted fields into a standard JSON schema
    normalized_data = {
        "vendor": "",
        "date": "",
        "total": "",
        "line_items": []
    }

    # Assuming extracted_data is in a format returned by Document AI
    for entity in extracted_data.get("entities", []):
        if entity["type"] == "Organization":
            normalized_data["vendor"] = entity["text"]
        elif entity["type"] == "Date":
            normalized_data["date"] = entity["text"]
        elif entity["type"] == "Money":
            normalized_data["total"] = entity["text"]
        elif entity["type"] == "Table":
            for row in entity["table"]["rows"]:
                line_item = {
                    "quantity": "",
                    "description": "",
                    "price": ""
                }
                for cell in row["cells"]:
                    if cell["text"].isdigit():
                        line_item["quantity"] = cell["text"]
                    elif cell["text"].replace('.', '', 1).isdigit():
                        line_item["price"] = cell["text"]
                    else:
                        line_item["description"] += cell["text"] + " "
                normalized_data["line_items"].append(line_item)

    return json.dumps(normalized_data)
